def transform(grid):
    out = [list(row) for row in grid]
    h, w = len(out), len(out[0])
    uniform_rows = {r for r, row in enumerate(out) if len(set(row)) == 1}
    uniform_cols = {c for c in range(w) if len({out[r][c] for r in range(h)}) == 1}
    for r in uniform_rows:
        out[r] = [2] * w
    for c in uniform_cols:
        for r in range(h):
            out[r][c] = 2
    return out
